const entrada = $input.first()?.json;
const texto = entrada?.csv_texto;

if (typeof texto !== 'string' || !texto.trim()) {
  throw new Error('Campo csv_texto ausente ou vazio');
}

const linhas = texto.replace(/\r\n?/g, '\n')
  .trim()
  .split('\n')
  .map(linha => linha.trim())
  .filter(Boolean);

const cabecalho = linhas.shift()?.replace(/^\uFEFF/, '').toLowerCase();

if (cabecalho !== 'perfil,produto,minimo,rentabilidade') {
  throw new Error('Cabeçalho inesperado: ' + cabecalho);
}

const produtos = linhas.map((linha, indice) => {
  const campos = linha.split(',').map(campo => campo.trim());

  if (campos.length !== 4) {
    throw new Error('Linha ' + (indice + 2) + ': esperados 4 campos');
  }

  const [perfil, produto, minimoTexto, rentabilidade] = campos;
  const minimo = Number(minimoTexto);

  if (!Number.isFinite(minimo) || minimo < 0) {
    throw new Error('Valor mínimo inválido na linha ' + (indice + 2));
  }

  return {
    json: {
      perfil,
      produto,
      minimo,
      rentabilidade
    }
  };
});

console.log('Produtos estruturados:', produtos.length);

return produtos;

const clientes = $('Webhook').first().json.body.clientes;
const produtos = $input.all().map(item => item.json);

if (!Array.isArray(clientes) || clientes.length === 0) {
  throw new Error('Lista de clientes ausente ou vazia');
}

function normalizarPerfil(valor) {
  return String(valor ?? '').trim().toLowerCase();
}

function converterSaldo(valor) {
  const texto = String(valor ?? '')
    .replace(/[^\d,.-]/g, '')
    .replace(/\./g, '')
    .replace(',', '.');

  const saldo = Number(texto);

  if (!Number.isFinite(saldo) || saldo < 0) {
    throw new Error('Saldo inválido: ' + valor);
  }

  return saldo;
}

return clientes.map(cliente => {
  const saldo = converterSaldo(cliente.saldo);

  const opcoes = produtos
    .filter(produto =>
      normalizarPerfil(produto.perfil) ===
        normalizarPerfil(cliente.perfil) &&
      saldo >= Number(produto.minimo)
    )
    .map(produto => ({
      produto: produto.produto,
      minimo: produto.minimo,
      rentabilidade: produto.rentabilidade
    }));

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      perfil: cliente.perfil,
      saldo,
      opcoes_elegiveis: opcoes
    }
  };
});

const textosPorPerfil = {
  Conservador: 'Seu perfil prioriza previsibilidade e estabilidade.',
  Moderado: 'Seu perfil busca equilibrar estabilidade e oscilação.',
  Arrojado: 'Seu perfil admite maior oscilação nos investimentos.'
};

const formatarMoeda = valor =>
  new Intl.NumberFormat('pt-BR', {
    style: 'currency',
    currency: 'BRL'
  }).format(valor);

return $input.all().map(item => {
  const cliente = item.json;
  const opcoes = cliente.opcoes_elegiveis;

  if (!Array.isArray(opcoes) || !Number.isFinite(cliente.saldo)) {
    throw new Error('Cliente com saldo ou opções inválidos');
  }

  const lista = opcoes.length
    ? opcoes.map(opcao =>
        '- ' + opcao.produto +
        ' | mínimo: ' + formatarMoeda(opcao.minimo) +
        ' | rentabilidade informada: ' + opcao.rentabilidade
      ).join('\n')
    : 'Nenhum produto fictício atende aos critérios de perfil e saldo.';

  const mensagem = [
    'Olá, ' + cliente.nome + '!',
    'Perfil: ' + cliente.perfil + '. ' +
      (textosPorPerfil[cliente.perfil] || 'Perfil não reconhecido.'),
    'Saldo informado: ' + formatarMoeda(cliente.saldo),
    'Opções ilustrativas da base da DIO:\n' + lista,
    'Material fictício para aprendizagem, sem recomendação financeira real.'
  ].join('\n\n');

  return { json: { ...cliente, mensagem } };
});
